  import express, { NextFunction, Request, Response } from "express";
  import type { InventoryService } from "../application/inventory-service";
  import type { OrderService } from "../application/order-service";
  import {
    DomainError,
    InsufficientStockError,
    InvalidTransitionError,
    NotFoundError,
    ValidationError,
  } from "../domain/errors";
  import { isOrderState, ORDER_STATES, OrderState } from "../domain/order";

  export interface AppServices {
    orders: OrderService;
    inventory: InventoryService;
  }

  export function createApp(services: AppServices): express.Express {
    const app = express();
    app.use(express.json());

    app.get("/health", (_req: Request, res: Response) => {
      res.json({ status: "ok" });
    });

    // Customer: place an order.
    app.post("/orders", (req: Request, res: Response) => {
      const body: unknown = req.body;
      if (!isRecord(body)) throw new ValidationError("Request body must be a JSON object");
      const { customerId, items } = body;
      if (typeof customerId !== "string" || customerId.trim() === "") {
        throw new ValidationError("customerId must be a non-empty string");
      }
      if (!Array.isArray(items)) throw new ValidationError("items must be an array");
      const parsedItems = items.map((item: unknown, i: number) => {
        if (!isRecord(item)) throw new ValidationError(`items[${i}] must be an object`);
        const { productId, quantity } = item;
        if (typeof productId !== "string" || productId === "") {
          throw new ValidationError(`items[${i}].productId must be a non-empty string`);
        }
        if (typeof quantity !== "number") {
          throw new ValidationError(`items[${i}].quantity must be a number`);
        }
        return { productId, quantity };
      });
      const order = services.orders.placeOrder({ customerId, items: parsedItems });
      res.status(201).json(order);
    });

    // Staff: list orders, optionally filtered by ?state=
    app.get("/orders", (req: Request, res: Response) => {
      const state = parseStateQuery(req.query["state"]);
      res.json(services.orders.listOrders(state));
    });

    app.get("/orders/:id", (req: Request, res: Response) => {
      res.json(services.orders.getOrder(param(req, "id")));
    });

    // Move an order to an explicit state: { "state": "paid" }
    app.post("/orders/:id/transitions", (req: Request, res: Response) => {
      const body: unknown = req.body;
      const state = isRecord(body) ? body["state"] : undefined;
      if (typeof state !== "string" || !isOrderState(state)) {
        throw new ValidationError(`state must be one of: ${ORDER_STATES.join(", ")}`);
      }
      res.json(services.orders.changeState(param(req, "id"), state));
    });

    // Convenience actions.
    app.post("/orders/:id/advance", (req: Request, res: Response) => {
      res.json(services.orders.advance(param(req, "id")));
    });

    app.post("/orders/:id/cancel", (req: Request, res: Response) => {
      res.json(services.orders.cancel(param(req, "id")));
    });

    // Staff: stock levels.
    app.get("/products", (_req: Request, res: Response) => {
      res.json(services.inventory.listStock());
    });

    app.get("/products/:id", (req: Request, res: Response) => {
      res.json(services.inventory.getStock(param(req, "id")));
    });

    app.use((_req: Request, res: Response) => {
      res.status(404).json({ error: "NotFound", message: "Route not found" });
    });

    app.use((err: unknown, _req: Request, res: Response, _next: NextFunction) => {
      const { status, body } = toErrorResponse(err);
      res.status(status).json(body);
    });

    return app;
  }

  function toErrorResponse(err: unknown): { status: number; body: Record<string, unknown> } {
    if (err instanceof InsufficientStockError) {
      return {
        status: 409,
        body: {
          error: err.name,
          message: err.message,
          productId: err.productId,
          requested: err.requested,
          available: err.available,
        },
      };
    }
    if (err instanceof InvalidTransitionError) {
      return { status: 409, body: { error: err.name, message: err.message } };
    }
    if (err instanceof NotFoundError) {
      return { status: 404, body: { error: err.name, message: err.message } };
    }
    if (err instanceof ValidationError || err instanceof DomainError) {
      return { status: 400, body: { error: err.name, message: err.message } };
    }
    if (err instanceof SyntaxError) {
      return { status: 400, body: { error: "ValidationError", message: "Malformed JSON body" } };
    }
    console.error(err);
    return { status: 500, body: { error: "InternalError", message: "Internal server error" } };
  }

  function isRecord(value: unknown): value is Record<string, unknown> {
    return typeof value === "object" && value !== null && !Array.isArray(value);
  }

  function param(req: Request, name: string): string {
    const value: unknown = req.params[name];
    if (typeof value !== "string" || value === "") {
      throw new ValidationError(`Missing path parameter '${name}'`);
    }
    return value;
  }

  function parseStateQuery(value: unknown): OrderState | undefined {
    if (value === undefined) return undefined;
    if (typeof value !== "string" || !isOrderState(value)) {
      throw new ValidationError(`state must be one of: ${ORDER_STATES.join(", ")}`);
    }
    return value;
  }

